insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('4c8157c8-58a2-59d5-aac7-8163174416db', 'chemistry'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9CH0', 'Topic 1: Atomic Structure and the Periodic Table', 0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6fb7003a-71ac-5ad1-a227-2b12b6c5c31e', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.1', 'know the structure of an atom in terms of electrons, protons and neutrons', 0, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('23b99aba-39ea-52e8-9391-1f130d6f861f', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.2', 'know the relative mass and relative charge of protons, neutrons and electrons', 1, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4842abe1-bdab-530f-b83e-c913cb5f190d', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.3', 'know what is meant by the terms ''atomic (proton) number'' and ''mass number''', 2, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a11e49c9-0f77-539e-9db9-ef8c05618512', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.4', 'be able to determine the number of each type of sub-atomic particle in an atom, molecule or ion from the atomic (proton) number and mass number', 3, 1.09) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7ff13445-3f0b-5d88-815e-e281b27584e4', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.5', 'understand the term ''isotopes''', 4, 0.74) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1bd756c7-2386-5d43-81f0-5cbbd9681d12', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.6', 'be able to define the terms ''relative isotopic mass'' and ''relative atomic mass'', based on the 12C scale', 5, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('26e7ea99-f21e-543c-a192-d7ac387bbfd8', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.7', 'understand the terms ''relative molecular mass'' and ''relative formula mass'', including calculating these values from relative atomic masses Definitions of these terms will not be expected. The term ''relative formula mass'' should be used for compounds with giant structures.', 6, 1.3) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e84e904d-c350-5126-beb0-33618f339036', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.8', 'be able to analyse and interpret data from mass spectrometry to calculate relative atomic mass from relative abundance of isotopes and vice versa', 7, 1.05) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d99d09c1-d43e-511d-a955-035fb2f6fbcf', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.9', 'be able to predict the mass spectra, including relative peak heights, for diatomic molecules, including chlorine', 8, 0.93) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('dd5eda2d-ecb4-5b06-86a1-000a5c4763d1', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.10', 'understand how mass spectrometry can be used to determine the relative molecular mass of a molecule Limited to the m/z value for the molecular ion, M+, giving the relative molecular mass of the molecule.', 9, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('77a87f21-9f39-516f-9bdd-000adfe96bb7', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.11', 'be able to define the terms ''first ionisation energy'' and ''successive ionisation energies''', 10, 0.89) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('79f1fff8-5866-5a0f-8c26-93e186b57e23', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.12', 'understand how ionisation energies are influenced by the number of protons, the electron shielding and the electron sub-shell from which the electron is removed', 11, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('78f9f748-06b1-596f-b0cb-29229ceee408', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.13', 'understand reasons for the general increase in first ionisation energy across a period', 12, 0.89) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('98806eef-5418-5757-a8b6-3f75b809c0f1', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.14', 'understand reasons for the decrease in first ionisation energy down a group', 13, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1163b355-cee8-57da-8622-ba38139a97ad', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.15', 'understand how ideas about electronic configuration developed from: i the fact that atomic emission spectra provide evidence for the existence of quantum shells ii the fact that successive ionisation energies provide evidence for the existence of quantum shells and the group to which the element belongs iii the fact that the first ionisation energy of successive elements provides evidence for electron sub-shells', 14, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('be922567-e443-57d0-9b7a-4fd00fc0d54b', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.16', 'know the number of electrons that can fill the first four quantum shells', 15, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6d93f7d8-358f-5837-94e4-ea4ec37b529e', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.17', 'know that an orbital is a region within an atom that can hold up to two electrons with opposite spins', 16, 0.83) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('28f060e5-d4e6-5d54-afab-93279c61706b', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.18', 'know the shape of an s-orbital and a p-orbital', 17, 0.65) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b23b2e31-9d52-5f6a-bf6f-98fd3a012cdb', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.19', 'know the number of electrons that occupy s, p and d-subshells', 18, 0.68) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0e4418a9-2b0b-5d28-b44c-22847ecdf550', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.20', 'know that electrons fill subshells singly, before pairing up, and that two electrons in the same orbital must have opposite spins', 19, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('06f160f5-3da7-5661-8620-b8bacb9b48a2', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.21', 'be able to predict the electronic configurations, using 1s notation and electrons- in-boxes notation, of: i atoms, given the atomic number, Z, up to Z = 36 ii ions, given the atomic number, Z, and the ionic charge, for s and p block ions only, up to Z = 36', 20, 1.64) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0281d0f0-ab19-5276-917b-9e7ff82019fb', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.22', 'know that elements can be classified as s, p and d-block elements', 21, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('147a3be7-f77c-5367-aafd-08c049d3adfc', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.23', 'understand that electronic configuration determines the chemical properties of an element', 22, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6c2ed51d-8c10-56fb-a2d4-7f75093b319f', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.24', 'understand periodicity in terms of a repeating pattern across different periods', 23, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2389f109-03af-5bad-8e21-d98a51fdf282', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.25', 'understand reasons for the trends in the following properties of the elements from periods 2 and 3 of the Periodic Table: i the melting and boiling temperatures of the elements, based on given data, in terms of structure and bonding ii ionisation energy based on given data or recall of the plots of ionisation energy versus atomic number', 24, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e5e8caf0-c497-5c8e-875c-50f9583f2c73', '4c8157c8-58a2-59d5-aac7-8163174416db', '1.26', 'be able to illustrate periodicity using data, including electronic configurations, atomic radii, melting and boiling temperatures and first ionisation energies', 25, 1.0) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('2584314d-c934-540c-b0bc-985f58be8a24', 'chemistry'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9CH0', 'Topic 2: Bonding and Structure', 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c193c775-d399-539b-b82b-9a5a62d3b24b', '2584314d-c934-540c-b0bc-985f58be8a24', '2.1', 'know that ionic bonding is the strong electrostatic attraction between oppositely charged ions', 0, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1208e09f-6921-5e50-bda7-e097345075a9', '2584314d-c934-540c-b0bc-985f58be8a24', '2.2', 'understand the effects that ionic radius and ionic charge have on the strength of ionic bonding', 1, 0.93) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('99d80a99-8fbb-51c2-9bc5-b0b546f6bb5c', '2584314d-c934-540c-b0bc-985f58be8a24', '2.3', 'understand the formation of ions in terms of electron loss or gain', 2, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3f382f3b-7a86-5309-a295-a46eba7f374e', '2584314d-c934-540c-b0bc-985f58be8a24', '2.4', 'be able to draw electronic configuration diagrams of cations and anions using dot-and-cross diagrams', 3, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('20a273a4-fe61-5db4-ab2c-bd4b729df872', '2584314d-c934-540c-b0bc-985f58be8a24', '2.5', 'understand reasons for the trends in ionic radii down a group and for a set of isoelectronic ions, e.g. N3– to Al3+', 4, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('559a99d6-58c3-557a-933a-927dac6e31ed', '2584314d-c934-540c-b0bc-985f58be8a24', '2.6', 'understand that the physical properties of ionic compounds and the migration of ions provide evidence for the existence of ions', 5, 1.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('87ebab3c-ba89-57a2-b797-f021e8c9d026', '2584314d-c934-540c-b0bc-985f58be8a24', '2.7', 'know that a covalent bond is the strong electrostatic attraction between two nuclei and the shared pair of electrons between them', 6, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('072e8248-335b-5140-9ec0-d19c200b4505', '2584314d-c934-540c-b0bc-985f58be8a24', '2.8', 'be able to draw dot-and-cross diagrams to show electrons in covalent substances, including: i molecules with single, double and triple bonds ii species exhibiting dative covalent (coordinate) bonding, including Al2Cl6 and ammonium ion', 7, 1.21) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9d636969-f8db-5763-8ff9-2018940cd5e5', '2584314d-c934-540c-b0bc-985f58be8a24', '2.9', 'understand the relationship between bond lengths and bond strengths for covalent bonds', 8, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d61f5dfe-244a-542a-bcfd-324104a545ab', '2584314d-c934-540c-b0bc-985f58be8a24', '2.10', 'understand that the shape of a simple molecule or ion is determined by the repulsion between the electron pairs that surround a central atom', 9, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5863471c-55b2-58e7-8413-cca97085baae', '2584314d-c934-540c-b0bc-985f58be8a24', '2.11', 'understand reasons for the shapes of, and bond angles in, simple molecules and ions with up to six outer pairs of electrons (any combination of bonding pairs and lone pairs) Examples should include BeCl2, BCl3, CH4, NH3, NH4+, H2O, CO2, PCl5(g) and SF6(g) and related molecules and ions; as well as simple organic molecules in this specification.', 10, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('366ddcb5-d7eb-5363-8fe0-9b62b4878fcc', '2584314d-c934-540c-b0bc-985f58be8a24', '2.12', 'be able to predict the shapes of, and bond angles in, simple molecules and ions analogous to those specified above using electron-pair repulsion theory', 11, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('91e36567-e3ef-5dc9-9045-4b4ecdfdce13', '2584314d-c934-540c-b0bc-985f58be8a24', '2.13', 'know that electronegativity is the ability of an atom to attract the bonding electrons in a covalent bond', 12, 0.8) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1687c63d-42ee-5054-8d06-55dd6f9d39d2', '2584314d-c934-540c-b0bc-985f58be8a24', '2.14', 'know that ionic and covalent bonding are the extremes of a continuum of bonding type and that electronegativity differences lead to bond polarity in bonds and molecules', 13, 0.94) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('53659f59-e413-5c91-811a-797dbd0e8d1c', '2584314d-c934-540c-b0bc-985f58be8a24', '2.15', 'understand that molecules with polar bonds may not be polar molecules and be able to predict whether or not a given molecule is likely to be polar', 14, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('93b57e1f-0207-55c7-a332-88096db81f70', '2584314d-c934-540c-b0bc-985f58be8a24', '2.16', 'understand the nature of intermolecular forces resulting from the following interactions: i London forces (instantaneous dipole – induced dipole) ii permanent dipoles iii hydrogen bonds', 15, 1.08) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ab01fd6f-2bf4-58d2-82fb-5db7f176f8b1', '2584314d-c934-540c-b0bc-985f58be8a24', '2.17', 'understand the interactions in molecules, such as H2O, liquid NH3 and liquid HF, which give rise to hydrogen bonding', 16, 0.98) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1af0de99-4e6a-5cff-9006-8674be26ef12', '2584314d-c934-540c-b0bc-985f58be8a24', '2.18', 'understand the following anomalous properties of water resulting from hydrogen bonding: i its relatively high melting temperature and boiling temperature ii the density of ice compared to that of water', 17, 1.16) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('812e4c0e-7bfc-5d33-8d3d-78ec3d2856ac', '2584314d-c934-540c-b0bc-985f58be8a24', '2.19', 'be able to predict the presence of hydrogen bonding in molecules analogous to those mentioned above', 18, 0.93) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c70513f5-8733-56a9-a052-79248387b2e0', '2584314d-c934-540c-b0bc-985f58be8a24', '2.20', 'understand, in terms of intermolecular forces, physical properties shown by materials, including: i the trends in boiling temperatures of alkanes with increasing chain length ii the effect of branching in the carbon chain on the boiling temperatures of alkanes iii the relatively low volatility (higher boiling temperatures) of alcohols compared to alkanes with a similar number of electrons iv the trends in boiling temperatures of the hydrogen halides, HF to HI', 19, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('49714d90-b1ba-57ca-9a96-9057bac64ddf', '2584314d-c934-540c-b0bc-985f58be8a24', '2.21', 'understand factors that influence the choice of solvents, including: i water, to dissolve some ionic compounds, in terms of the hydration of the ions ii water, to dissolve simple alcohols, in terms of hydrogen bonding iii water, as a poor solvent for compounds (to include polar molecules such as halogenoalkanes), in terms of inability to form hydrogen bonds iv non-aqueous solvents, for compounds that have similar intermolecular forces to those in the solvent', 20, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6cf82171-0c94-5d8b-9e86-f68e57c30082', '2584314d-c934-540c-b0bc-985f58be8a24', '2.22', 'know that metallic bonding is the strong electrostatic attraction between metal ions and the delocalised electrons', 21, 0.76) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ef31fbdc-8944-50e7-8917-ae1780589242', '2584314d-c934-540c-b0bc-985f58be8a24', '2.23', 'know that giant lattices are present in: i ionic solids (giant ionic lattices) ii covalently bonded solids, such as diamond, graphite and silicon(IV) oxide (giant covalent lattices) iii solid metals (giant metallic lattices)', 22, 1.04) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('19f76f5b-13e6-5019-b828-40fa91ada444', '2584314d-c934-540c-b0bc-985f58be8a24', '2.24', 'know that the structure of covalently bonded substances such as iodine, I2, and ice, H2O, is simple molecular', 23, 0.8) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4b759dc3-dbc8-5fc4-bb9e-15503b916896', '2584314d-c934-540c-b0bc-985f58be8a24', '2.25', 'know the different structures formed by carbon atoms, including graphite, diamond and graphene', 24, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a56e798b-f0fd-5b9c-a087-36433b98b175', '2584314d-c934-540c-b0bc-985f58be8a24', '2.26', 'be able to predict the type of structure and bonding present in a substance from numerical data and/or other information', 25, 1.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('963d8565-5c76-5986-aac4-44647ca8becc', '2584314d-c934-540c-b0bc-985f58be8a24', '2.27', 'be able to predict the physical properties of a substance, including melting and boiling temperature, electrical conductivity and solubility in water, in terms of: i the types of particle present (atoms, molecules, ions, electrons) ii the structure of the substance iii the type of bonding and the presence of intermolecular forces, where relevant', 26, 1.45) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('ec580dd4-8030-5756-a9e7-7d023dfd790c', 'chemistry'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9CH0', 'Topic 3: Redox I', 2) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e5c11980-cb38-5c2a-a51c-99ff36d603c8', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.1', 'know what is meant by the term ''oxidation number''', 0, 0.65) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1c6ae765-4eef-5047-b1b7-afc61f296d93', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.2', 'be able to calculate the oxidation number of elements in compounds and ions The use of oxidation numbers in peroxides and metal hydrides is expected.', 1, 1.08) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b17e8ec4-230f-569a-b463-931e1d8cb57d', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.3', 'understand oxidation and reduction in terms of electron transfer and changes in oxidation number, applied to reactions of s- and p-block elements', 2, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('74703733-4f35-5e3c-a93f-61e0b11790b5', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.4', 'understand oxidation and reduction in terms of electron loss or electron gain', 3, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ac385986-936c-5597-bdff-64dc76bf9071', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.5', 'know that oxidising agents gain electrons', 4, 0.6) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0091ef53-5bbd-58b7-b3cb-ef198255ec8a', 'ec580dd4-8030-5756-a9e7-7d023dfd790c', '3.6', 'know that reducing agents lose electrons', 5, 0.6) on conflict (id) do nothing;
