insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4187b4af-05f9-5c9c-be9d-c1d999e7dbdc', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.6', 'understand reasons for the trends in thermal stability of the nitrates and the carbonates of the elements in Groups 1 and 2 in terms of the size and charge of the cations involved', 5, 1.21) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('93abdf87-d8ca-51ef-b2d6-f5a5d5d40606', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.7', 'understand the formation of characteristic flame colours by Group 1 and 2 compounds in terms of electron transitions Students will be expected to know the flame colours for Groups 1 and 2 compounds.', 6, 1.21) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6e79a8de-729c-594a-b530-619d4a3f66c5', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.8', 'understand experimental procedures to show: i patterns in thermal decomposition of Group 1 and 2 nitrates and carbonates ii flame colours in compounds of Group 1 and 2 elements', 7, 1.14) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b6511c48-260b-5494-94ad-624465d769b1', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.9', 'understand reasons for the trends in melting and boiling temperatures, physical state at room temperature, and electronegativity for Group 7 elements', 8, 1.01) on conflict (id) do nothing;
