insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1d53d890-f980-5f70-a925-5f2cb57fc45e', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.11', 'understand the trend in reactivity of Group 7 elements in terms of the redox reactions of Cl2, Br2 and I2 with halide ions in aqueous solution, followed by the addition of an organic solvent', 10, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('05ab8ecc-8dec-511f-b49a-4db0fb52d2c1', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.12', 'understand, in terms of changes in oxidation number, the following reactions of the halogens: i oxidation reactions with Group 1 and 2 metals ii the disproportionation reaction of chlorine with water and the use of chlorine in water treatment iii the disproportionation reaction of chlorine with cold, dilute aqueous sodium hydroxide to form bleach iv the disproportionation reaction of chlorine with hot alkali v reactions analogous to those specified above', 11, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a3e3a270-62da-5b16-b2e8-8c488eab20d4', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.13', 'understand the following reactions: i solid Group 1 halides with concentrated sulfuric acid, to illustrate the trend in reducing ability of the hydrogen halides ii precipitation reactions of the aqueous anions Cl–, Br– and I– with aqueous silver nitrate solution, followed by aqueous ammonia solution iii hydrogen halides with ammonia and with water (to produce acids)', 12, 1.45) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ee8d4e11-68d5-5471-98ec-cf815cda0200', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.14', 'be able to make predictions about fluorine and astatine and their compounds, in terms of knowledge of trends in halogen chemistry', 13, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3aae3b44-4834-5dd7-96f1-013ac9856616', '6cb61646-31e0-5277-bcb7-29cca927c00a', '4.15', 'know reactions, including ionic equations where appropriate, for identifying: i carbonate ions, CO32-, and hydrogencarbonate ions, HCO3–, using an aqueous acid to form carbon dioxide ii sulfate ions, SO42-, using acidified barium chloride solution iii ammonium ions, NH4+, using sodium hydroxide solution and warming to form ammonia Tests for halide ions and for the ions of Group 1 and 2 metals are also required, but are covered elsewhere in this Topic.', 14, 1.28) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('8323fc5b-09eb-5f55-9c65-df7cc410b546', 'chemistry'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9CH0', 'Topic 5: Formulae, Equations and Amounts of Substance', 4) on conflict (id) do nothing;
