insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f2492467-d741-55a3-92de-9b4758576e02', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.4', 'know what is meant by the terms ''empirical formula'' and ''molecular formula''', 3, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('09280d87-0e7a-58b2-b6ad-34861f0c872d', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.5', 'be able to use experimental data to calculate i. empirical formulae ii. molecular formulae including the use of pV = nRT for gases and volatile liquids Calculations of empirical formula may involve composition by mass or percentage composition by mass data.', 4, 1.53) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3ddd398e-81aa-515f-bb71-ef48792f6bc0', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.6', 'be able to write balanced full and ionic equations, including state symbols, for chemical reactions', 5, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d1677ba0-9707-5a0e-b3dc-2036f7e9b85c', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.7', 'be able to calculate amounts of substances (in mol) in reactions involving mass, volume of gas, volume of solution and concentration These calculations may involve reactants and/or products.', 6, 1.13) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e1eff968-451c-59ed-9cfe-4df86d390ab5', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.8', 'be able to calculate reacting masses from chemical equations, and vice versa, using the concepts of amount of substance and molar mass', 7, 1.03) on conflict (id) do nothing;
