insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('facf7df4-74dd-5fb2-8bed-41a84eabcb0c', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.10', 'be able to calculate reacting volumes of gases from chemical equations, and vice versa, using the concepts of molar volume of gases', 9, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('67e05d78-152f-5916-8291-e914d3e28cee', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.11', 'be able to calculate solution concentrations, in mol dm-3 and g dm-3, including simple acid-base titrations using a range of acids, alkalis and indicators The use of both phenolphthalein and methyl orange as indicators will be expected.', 10, 1.27) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b3cc8f26-7ed8-5202-bf98-067a42289452', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.12', 'be able to: i calculate measurement uncertainties and measurement errors in experimental results ii comment on sources of error in experimental procedures', 11, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('18d38894-0c43-504e-a1cd-b747d1d7408b', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.13', 'understand how to minimise the percentage error and percentage uncertainty in experiments involving measurements', 12, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2bfb5155-1482-5d3c-ae81-84625d4d7f0e', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.14', 'be able to calculate percentage yields and percentage atom economies using chemical equations and experimental results molar mass of the desired productAtom economy of a reaction = × 100% sum of the molar masses of all products', 13, 1.47) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('98ca6e95-a2ef-57c0-9eaf-157f6326d28f', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.15', 'be able to relate ionic and full equations, with state symbols, to observations from simple test tube reactions, to include: i displacement reactions ii reactions of acids iii precipitation reactions', 14, 1.16) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2ce23a83-513e-5f3a-8399-4a8dc608f0a4', '8323fc5b-09eb-5f55-9c65-df7cc410b546', '5.16', 'understand risks and hazards in practical procedures and suggest appropriate precautions where necessary', 15, 0.89) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', 'chemistry'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9CH0', 'Topic 6: Organic Chemistry I', 5) on conflict (id) do nothing;
