insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f9ec38e3-dd31-532c-88fe-c6c2d712669f', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.2', 'be able to represent organic molecules using empirical formulae, molecular formulae, general formulae, structural formulae, displayed formulae and skeletal formulae', 1, 1.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3e49e7be-31ed-51d7-bcfd-b92e15ea495e', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.3', 'know what is meant by the terms ''homologous series'' and ''functional group''', 2, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ded7f0d9-80a6-5750-a3d8-9ee24c362112', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.4', 'be able to name compounds relevant to this specification using the rules of International Union of Pure and Applied Chemistry (IUPAC) nomenclature Students will be expected to know prefixes for compounds up to C10', 3, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('65297949-c499-5db0-b933-4fdb42d8d808', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.5', 'be able to classify reactions as addition, elimination, substitution, oxidation, reduction, hydrolysis or polymerisation', 4, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('33aaba68-f340-52f4-881f-c7e31ee8f0a7', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.6', 'understand the term ''structural isomerism'' and determine the possible structural, displayed and skeletal formulae of an organic molecule, given its molecular formula', 5, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6970b8ff-70cf-52fb-9757-cbcb93476e70', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.7', 'understand the term ''stereoisomerism'', as illustrated by E/Z isomerism (including cis-trans isomerism where two of the substituent groups are the same)', 6, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3874b7b9-2461-594c-b0d1-d7e90bfaa486', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.8', 'know the general formula for alkanes', 7, 0.6) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a26e8aa3-0cf6-5a84-af7f-771ee737c403', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.9', 'know that alkanes and cycloalkanes are saturated hydrocarbons', 8, 0.64) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ea0ec822-173b-5ed0-9f96-a864a85963a7', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.10', 'understand that alkane fuels are obtained from the fractional distillation, cracking and reforming of crude oil Reforming is described as the processing of straight-chain hydrocarbons into branched-chain alkanes and cyclic hydrocarbons for efficient combustion.', 9, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bc5e2691-99e5-5362-a3bb-9563d09a790c', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.11', 'know that pollutants, including carbon monoxide, oxides of nitrogen and sulfur, carbon particulates and unburned hydrocarbons, are formed during the combustion of alkane fuels', 10, 0.89) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('78e3ebd8-efab-5729-b5bf-bee2c05fe459', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.12', 'understand the problems arising from pollutants from the combustion of fuels, limited to the toxicity of carbon monoxide and the acidity of oxides of nitrogen and sulfur', 11, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('674ceb6b-1ebe-58fb-8504-ec7457c94f5f', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.13', 'understand how the use of a catalytic converter solves some problems caused by pollutants', 12, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d4c733d1-f0cb-5225-8a32-b4ff4906d414', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.14', 'understand the use of alternative fuels, including biodiesel and alcohols derived from renewable sources such as plants, in terms of a comparison with non-renewable fossil fuels', 13, 1.09) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('113ee5cc-b460-5eaf-ad54-f3ef45fd9bea', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.15', 'know that a radical: i is a species with an unpaired electron and is represented in mechanisms by a single dot ii is formed by homolytic fission of a covalent bond and results in the formation of radicals', 14, 1.12) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b7c3b849-3368-5ece-bfdd-b8db769798fb', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.16', 'understand the reactions of alkanes with: i oxygen in air (combustion) ii halogens, in terms of the mechanism of radical substitution through initiation, propagation and termination steps The use of curly half-arrows is not expected in this mechanism.', 15, 1.29) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('290196b0-9b81-5ed1-9974-61869b3cca9b', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.17', 'understand the limitations of the use of radical substitution reactions in the synthesis of organic molecules, in terms of further substitution reactions and the formation of a mixture of products', 16, 1.16) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('690aa8df-a79a-5de0-ac8c-834af9a14e94', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.18', 'know the general formula for alkenes', 17, 0.6) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2b8c3dd4-57e4-5336-8971-4f27ce466c41', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.19', 'know that alkenes and cycloalkenes are unsaturated hydrocarbons', 18, 0.64) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5029bab7-e4a4-5966-a0d1-13b474787897', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.20', 'understand the bonding in alkenes in terms of σ- and π- bonds', 19, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e144ecfe-9004-515e-a2c6-3b9e0ea8745d', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.21', 'know what is meant by the term ''electrophile''', 20, 0.64) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4c74c6ce-60a8-5bfb-93a8-0db521a7749c', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.22', 'understand the addition reactions of alkenes with: i hydrogen, in the presence of a nickel catalyst, to form an alkane Knowledge of the application of this reaction to the manufacture of margarine by catalytic hydrogenation of unsaturated vegetable oils is expected. ii halogens to produce dihalogenoalkanes iii hydrogen halides to produce halogenoalkanes iv steam, in the presence of an acid catalyst, to produce alcohols v potassium manganate(VII), in acid conditions, to oxidise the double bond and produce a diol', 21, 1.45) on conflict (id) do nothing;
