insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5c692326-0fd8-5287-9cfc-1b04a5298e63', 'e22e2d45-285e-57fc-a6d2-9df4b07c6bd0', '6.26', 'know that alkenes form polymers through addition polymerisation Be able to identify the repeat unit of an addition polymer given the monomer, and vice versa.', 25, 0.91) on conflict (id) do nothing;
